{"protocolSection":{"identificationModule":{"nctId":"NCT05801029","orgStudyIdInfo":{"id":"D5162C00052"},"organization":{"fullName":"AstraZeneca","class":"INDUSTRY"},"briefTitle":"A Study to Investigate Safety and Efficacy of Osimertinib and Amivantamab in Participants With Non-small Cell Lung Cancer With Common Epidermal Growth Factor Receptor Mutations","officialTitle":"A Phase II, Open-label, Single-arm, Multi-centre Study to Evaluate the Safety and Efficacy of Osimertinib With Amivantamab as First-line Treatment in Participants With Epidermal Growth Factor Receptor Mutation-Positive, Locally Advanced or Metastatic Non-small Cell Lung Cancer (OSTARA)","acronym":"OSTARA"},"statusModule":{"statusVerifiedDate":"2026-09","overallStatus":"ACTIVE_NOT_RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2023-07-18","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2027-10-01","type":"ESTIMATED"},"completionDateStruct":{"date":"2027-10-01","type":"ESTIMATED"},"studyFirstSubmitDate":"2023-03-24","studyFirstSubmitQcDate":"2023-03-24","studyFirstPostDateStruct":{"date":"2023-04-06","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-09-04","lastUpdatePostDateStruct":{"date":"2026-09-08","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"AstraZeneca","class":"INDUSTRY"},"collaborators":[{"name":"Parexel","class":"INDUSTRY"}]},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This study will assess the safety and efficacy of Osimertinib with Amivantamab as First-line Treatment in Participants with Epidermal Growth Factor Receptor Mutation-Positive, Locally Advanced or Metastatic Non-small Cell Lung Cancer (NSCLC).","detailedDescription":"This is a Phase II, open-label, single-arm, multi-centre study to assess the safety and efficacy of osimertinib with amivantamab as first-line treatment in adult participants with a local preexisting positive approved tissue test result for EGFRm (Ex19del or L858R), locally advanced (clinical stage IIIB, IIIC), metastatic (clinical stage IVA or IVB), or recurrent non-squamous NSCLC.

This study consists of screening period of 28 days, followed by the study intervention period wherein the participant receives treatment from Day 1 until disease progression or study intervention discontinuation. Participants will be followed up at week 6 (± 1 week), week 12 (± 1 week), then every 12 weeks (± 1 week) until radiological disease progression. Survival follow up will be performed every 12 weeks. Upon study intervention discontinuation a 28 day follow up visit will be performed."},"conditionsModule":{"conditions":["Non-Small Cell Lung Cancer (NSCLC)"],"keywords":["NSCLC","Non squamous","Epidermal Growth Factor Receptor (EGFR)","Epidermal Growth Factor Receptor mutation (EGFRm)"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE2"],"designInfo":{"allocation":"NA","interventionModel":"SINGLE_GROUP","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":60,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Osimertinib+Amivantamab","type":"EXPERIMENTAL","description":"Participants will receive osimertinib and amivantamab.","interventionNames":["Drug: Osimertinib","Drug: Amivantamab"]}],"interventions":[{"type":"DRUG","name":"Osimertinib","description":"Osimertinib will be administered as 80 mg oral tablet once daily (from Day 2) until progression of disease or until a study intervention discontinuation criterion is met.","armGroupLabels":["Osimertinib+Amivantamab"]},{"type":"DRUG","name":"Amivantamab","description":"Amivantamab will be administered as an IV infusion at 1050 mg (\< 80 kg body weight) or 1400mg (≥ 80 kg body weight) (in 28-day cycles: once weekly in Cycle 1 (with a split dose on Days 1 to 2) and then every 2 weeks in subsequent cycles) until progression of disease or until a study intervention discontinuation criterion is met. The first cycle dose is spilt over 2 days- 350 mg on day 1 and 700 mg \[body weight \< 80 kg\] or 1050 mg \[body weight ≥ 80 kg\] on day 2.","armGroupLabels":["Osimertinib+Amivantamab"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Number of participants with adverse events (AEs)","description":"To assess the safety and tolerability of osimertinib plus amivantamab in participants with EGFR mutation-positive, locally advanced, or metastatic NSCLC.","timeFrame":"From screening (Day-28) to survival follow up (Approximately 52 months after the first participant is dosed)"},{"measure":"Progression Free Survival (PFS)","description":"The time from date of first dose of study intervention until progression per RECIST 1.1 as assessed by the investigator at the local site, or death due to any cause. The analysis will include all dosed participants. All events will be included, regardless of whether the participant withdraws from therapy, receives another anti-cancer therapy or clinically progresses prior to RECIST 1.1.","timeFrame":"From date of first dose of study intervention until radiological disease progression or death due to any cause (Approximately 52 months after the first participant is dosed)"}],"secondaryOutcomes":[{"measure":"Overall Survival (OS)","description":"Time from date of first dose of study intervention until the date of death due to any cause. The analysis will include all dosed participants. All deaths will be included, regardless of whether the participant withdraws from therapy or receives another anti-cancer therapy.","timeFrame":"From date of first dose of study intervention until death due to any cause. Landmarks at 18 and 24 months. (Approximately 52 months after the first participant is dosed)"},{"measure":"Objective Response Rate (ORR)","description":"The proportion of participants who have a confirmed complete response (CR) or confirmed partial response (PR), as determined by the investigator at local site per RECIST 1.1. The analysis will include all dosed participants with measurable disease at baseline.","timeFrame":"From screening (Day -28) to radiological disease progression (Approximately 52 months after the first participant is dosed)"},{"measure":"Duration of Response (DoR)","description":"The time from the date of first documented response until date of documented progression per RECIST 1.1 as assessed by the investigator at local site or death due to any cause. The analysis will include all dosed participants with measurable disease at baseline who have a confirmed response.","timeFrame":"From screening (Day -28) to radiological disease progression (Approximately 52 months after the first participant is dosed)"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Histologically or cytologically documented non-squamous NSCLC. NSCLC of mixed histology is allowed.
* Newly diagnosed locally advanced or metastatic NSCLC or recurrent non-squamous NSCLC, not amenable to curative surgery or radiotherapy.
* WHO PS of 0 to 1 with no deterioration over the 2 weeks prior to enrolment.
* Minimum life expectancy \> 12 weeks at Day 1.
* Confirmation by the local laboratory that the tumour harbours one of the 2 common EGFRm known to be associated with (Epidermal Growth Factor Receptor- Tyrosine Kinase Inhibitor) EGFR-TKI sensitivity.
* At least 1 lesion that can be accurately measured at baseline as ≥10 mm in the longest diameter with computed tomography (CT) or magnetic resonance imaging (MRI) and that is suitable for accurate repeated measurements.
* Contraceptive use by males or females should be consistent with local regulations

Exclusion Criteria:

* Any evidence of diseases, history of allogenic organ transplant, which in the investigator's opinion makes it undesirable for the participant to participate in the study or would jeopardise compliance with protocol.
* Refractory nausea and vomiting, chronic gastrointestinal diseases, inability to swallow the osimertinib, or previous significant bowel resection that would preclude adequate absorption distribution, metabolism, or excretion of osimertinib.
* History of another primary malignancy except for malignancy treated with curative intent with no known active disease ≥2 years.
* Any unresolved toxicities from prior therapy with Common Terminology Criteria for Adverse Events CTCAE) Grade ≥1, at the time of first dose of study intervention, with the exception of alopecia and Grade 2 prior platinum therapy related neuropathy.
* Spinal cord compression or brain metastases unless asymptomatic, stable, and not requiring corticosteroids for at least 2 weeks prior to start of study intervention.
* Active infection, including tuberculosis and infections with HBV (verified by known positive HBsAg result) or HCV.
* Should participants with HIV infection be included, patients are only eligible if they meet the criteria per protocol.
* Patient with protocol defined cardiac issue.
* History of interstitial lung disease (ILD), drug-induced ILD, radiation pneumonitis that required steroid treatment, or any evidence of clinically active ILD.
* Any concomitant medications known to be associated with Torsade de Pointes.
* Prior exposure to any systemic anti-cancer therapy for advanced NSCLC not amenable to curative surgery or radiation including chemotherapy, biologic therapy, immunotherapy, or any investigational drug.
* Any concurrent anti-cancer treatment without an adequate washout period prior to the first dose of study intervention.
* Palliative radiotherapy with a limited field of radiation within 2 weeks, or with wide field of radiation or to more than 30% of the bone marrow within 4 weeks, prior to the first dose of study intervention.
* Major surgical procedure or significant traumatic injury.
* Current use of medications or herbal supplements known to be strong inducers of CYP 3A4.
* Prior treatment with an EGFR-TKI.
* Participants with a history of hypersensitivity, or intolerance to the active or inactive excipients of osimertinib, amivantamab, or recommended pre-treatments of amivantamab or drugs with a similar chemical structure or class to these drugs.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","maximumAge":"130 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"locations":[{"facility":"Research Site","city":"Hong Kong","zip":"150001","country":"Hong Kong","geoPoint":{"lat":22.27832,"lon":114.17469}},{"facility":"Research Site","city":"Hong Kong","zip":"999077","country":"Hong Kong","geoPoint":{"lat":22.27832,"lon":114.17469}},{"facility":"Research Site","city":"Hong Kong","country":"Hong Kong","geoPoint":{"lat":22.27832,"lon":114.17469}},{"facility":"Research Site","city":"George Town","zip":"10990","country":"Malaysia","geoPoint":{"lat":5.41123,"lon":100.33543}},{"facility":"Research Site","city":"Kota Bharu","zip":"15586","country":"Malaysia","geoPoint":{"lat":6.12361,"lon":102.24333}},{"facility":"Research Site","city":"Kuala Lumpur","zip":"50586","country":"Malaysia","geoPoint":{"lat":3.1412,"lon":101.68653}},{"facility":"Research Site","city":"Kuala Lumpur","zip":"59100","country":"Malaysia","geoPoint":{"lat":3.1412,"lon":101.68653}},{"facility":"Research Site","city":"Kuantan","zip":"25100","country":"Malaysia","geoPoint":{"lat":3.8077,"lon":103.326}},{"facility":"Research Site","city":"Kuching","zip":"93200","country":"Malaysia","geoPoint":{"lat":1.55,"lon":110.33333}},{"facility":"Research Site","city":"Singapore","zip":"169610","country":"Singapore","geoPoint":{"lat":1.28967,"lon":103.85007}},{"facility":"Research Site","city":"Singapore","zip":"308433","country":"Singapore","geoPoint":{"lat":1.28967,"lon":103.85007}},{"facility":"Research Site","city":"Anyang-si","zip":"14068","country":"South Korea","geoPoint":{"lat":37.3925,"lon":126.92694}},{"facility":"Research Site","city":"Busan","zip":"49241","country":"South Korea","