{"protocolSection":{"identificationModule":{"nctId":"NCT00348595","orgStudyIdInfo":{"id":"J0798"},"secondaryIdInfos":[{"id":"RV-PCA-PI-069"},{"id":"NA_00013597","type":"OTHER","domain":"JHM IRB"},{"id":"J0798","type":"OTHER","domain":"JHM IRB"}],"organization":{"fullName":"Sidney Kimmel Comprehensive Cancer Center at Johns Hopkins","class":"OTHER"},"briefTitle":"Study of 2 Different Doses of Revlimid in Biochemically Relapse Prostate Cancer","officialTitle":"Phase I/II Double Blinded Randomized Study to Determine the Tolerability and Efficacy of 2 Different Doses of Revlimid (CC-5013, Lenalidomide) in Biochemically Relapsed Prostate Cancer Patients (M0) After Local Treatment"},"statusModule":{"statusVerifiedDate":"2019-04","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2006-07-20","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2016-06-29","type":"ACTUAL"},"completionDateStruct":{"date":"2016-06-29","type":"ACTUAL"},"studyFirstSubmitDate":"2006-06-30","studyFirstSubmitQcDate":"2006-06-30","studyFirstPostDateStruct":{"date":"2006-07-04","type":"ESTIMATED"},"resultsFirstSubmitDate":"2019-03-21","resultsFirstSubmitQcDate":"2019-04-11","resultsFirstPostDateStruct":{"date":"2019-04-12","type":"ACTUAL"},"lastUpdateSubmitDate":"2019-04-11","lastUpdatePostDateStruct":{"date":"2019-04-12","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Sidney Kimmel Comprehensive Cancer Center at Johns Hopkins","class":"OTHER"},"collaborators":[{"name":"Celgene Corporation","class":"INDUSTRY"}]},"oversightModule":{"oversightHasDmc":true},"descriptionModule":{"briefSummary":"The primary objectives of the study are:

* To evaluate feasibility, safety and tolerance of 6 months administration of Revlimid at 5mg/day and 25mg/day, given orally in subjects with prostate cancer with evidence of biochemical relapse (M0) following local treatment (i.e., surgery or radiation).
* To assess the rate of PSA (prostatic specific antigen) progression at 6 months after treatment with 5mg/day and 25mg/day of Revlimid (CC-5013) in patients with evidence of biochemical relapse after local therapy.

The secondary objectives of the study are:

* To provide preliminary assessments on the effects of Revlimid (CC-5013) at 5mg/day and 25mg/day on various PSA constructs in the subject population (i.e., PSADT \[Prostatic Specific Antigen Doubling Time\] and PSA slope) by comparing pre and post treatment patterns in each arm.
* To evaluate preliminary pharmacodynamic correlations between serum revlimid concentrations and toxicity, PSA constructs and other evidence of disease progression.","detailedDescription":"Carcinoma of the prostate in the most commonly diagnosed malignancy among men in this country with approximately 232,090 new cases expected to be diagnosed in 2005. Unfortunately, despite local treatment, many men will demonstrate evidence of PSA recurrence. At the present time, there is no standard treatment fo these patients. The management of patients with PSA recurrence remains greatly controversial. Androgen deprivation is frequently employed in patients with evidence of rising PSA levels despite the fact that the effects on quantity and quality of life of androgen deprivation therapy at this stage, remains un-established. Toxicity of androgen deprivation therapy is a major factor to be considered in the decision process of employing the modality of treatment in patients with no symptoms associated with this disease. Because patients with biochemical relapse are mostly asymptomatic and typically have long survivals and disease free survivals, mush of the focus of new drug development has been with the use of non-cytotoxic compounds. This study is intended to provide preliminary evidence of a biological effect in a dose response manner assessing the effects of Revlimid (CC-5013) on PSA."},"conditionsModule":{"conditions":["Prostate Cancer"],"keywords":["Prostate Cancer"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE1","PHASE2"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"TRIPLE","whoMasked":["PARTICIPANT","CARE_PROVIDER","INVESTIGATOR"]}},"enrollmentInfo":{"count":77,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"1","type":"ACTIVE_COMPARATOR","description":"5mg/day Arm: one 5 mg active Revlimid capsule and one 25 mg matched placebo capsules PO QAM (every morning) (at approximately the same time) days 1-21 days (28-day cycles).","interventionNames":["Drug: Revlimid"]},{"label":"2","type":"ACTIVE_COMPARATOR","description":"25 mg/day Arm: one 25 mg active Revlimid capsule and one 5 mg matched placebo capsule PO QAM (every morning) (at approximately the same time) days 1-21 (28 day cycles).","interventionNames":["Drug: Revlimid"]}],"interventions":[{"type":"DRUG","name":"Revlimid","description":"one 5 mg/day capsule or one 25 mg/day capsule with matched placebo capsule day 1-21 (28 day cycle)","armGroupLabels":["1","2"],"otherNames":["Lenalidomide"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Safety, Feasibility and Tolerance of Revlimid as Assessed by Number of Participants Experiencing Grade 3 and 4 Adverse Events.","description":"Number of participants experiencing Grade 3 and 4 adverse events as defined by the National Cancer Institute Common Toxicity Criteria version 3.0","timeFrame":"6 months post-intervention"},{"measure":"Number of Participants With Prostate-specific Antigen (PSA) Progression","description":"Number of participants with greater than or equal to 25% increase in PSA at 6 months","timeFrame":"6 months post-intervention"},{"measure":"Change in of PSA Slope","description":"Mean change in PSA slope from baseline to 6 months. PSA slope was calculated using the regression of log PSA over 6 months in each patient. A negative mean change in PSA slope reflects a better outcome.","timeFrame":"Change from baseline to 6 months post-intervention"}],"secondaryOutcomes":[{"measure":"Plasma Concentration of Revilimid at Steady State","description":"Mean plasma concentration (ng/mL) of Revilimid at steady state (Day 21 of second treatment cycle)","timeFrame":"Day 21 of second treatment cycle"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Histologically confirmed diagnosis of adenocarcinoma of the prostate (M0) with evidence of biochemical relapse after local therapy (i.e., surgery, radiation therapy, or both.) Baseline PSA must be greater or equal to 1 ng/ml.
* Confirmed rise in PSA shown by 2 PSA values at least 1 month apart, higher than a reference value noted within 6 months of study entry. Interim PSA values during the immediate pre-study six-month interval may demonstrate a "fluctuation" including a decline, however the study baseline PSA must have shown a rise within the pre-study 6-months period. Baseline PSA's must be determined within 4 weeks of study entry.
* All previous local modalities of treatment, including radiation and surgery, must have been discontinued at least 4 weeks prior to treatment in this study. May have received prior systemic chemotherapy, hormonal therapy, biologic or vaccine therapy. All treatment must have been discontinued for more than 6 months prior to study entry.
* Patients receiving intermittent hormonal therapy for their rising PSA state are considered eligible if testosterone level is above 150 ng/dl and treatment was discontinued greater than 6 months
* No clinical or radiological evidence of distant metastases (excluding prostascint scan).
* Serum testosterone \> 150 ng/ml
* Disease free of prior malignancies for more than 5 years with exception of currently treated basal cell, squamous cell carcinoma of the skin, or carcinoma "in situ" of the breast.
* Able to take aspirin (ASA 81 or 325 mg) daily as prophylactic anticoagulation (patients intolerant to ASA may use low molecular weight heparin). Lenalidomide increases the risk of thrombotic events in patients who are at high risk or with a history a thrombosis, in particular when combined with other drugs known to cause thrombosis.

Exclusion Criteria:

* Any serious medical condition, laboratory abnormality, or psychiatric illness that would prevent the subject from signing the informed consent form.
* Any condition, including the presence of laboratory abnormalities, which places the subject at unacceptable risk if he/she were to participate in the study or confounds the ability to interpret data from the study.
* Known hypersensitivity to thalidomide.
* The development of erythema nodosum if characterized by a desquamating rash while taking thalidomide or similar drugs.
* Any prior use of Revlimid® (CC-5013).
* Concurrent use of other anti-cancer agents or treatments.
* Known brain metastases.
* Known positive for HIV or infectious hepatitis, type A, B or C.
* Any evidence of metastatic disease.
* Any increase in PSA while receiving neo-adjuvant or adjuvant therapy or intermittent hormonal therapy.
* More than one prior biologic or vaccine therapy","healthyVolunteers":true,"sex":"MALE","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Mario A Eisenberger, MD","affiliation":"Sidney Kimmel Comprehensive Cancer Center at Johns Hopkins","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"The Harry and Jeanette Weinberg Building","city":"Baltimore","state":"Maryland","zip":"21230","country":"United States","geoPoint":{"lat":39.29038,"lon":-76.61219}}]},"ipdSharingStatementModule":{"ipdSharing":"NO"}},"resultsSection":{"participantFlowModule":{"preAssignmentDetails":"17 subjects were screen failures","groups":[{"id":"FG000","title":"Revlimid 5mg/Day","description":"One 5 mg active Revlimid capsule and one 25 mg matched placebo capsule given by mouth daily in the morning (at approximately the same time) on days 1-21 (28-day cycles)."},{"id":"FG001","title":"Revlimid 25mg/Day","description":"One 25 mg active Revlimid capsule and one 5 mg matched placebo capsule given by mouth daily in the morning (at approximately the same time) on days 1-21 (28-day cycles)."}],"periods":[{"title":"Overall Study","milestones":[{"type":"STARTED","achievements":[{"groupId":"FG000","numSubjects":"26"},{"groupId":"FG001","numSubjects":"34"}]},{"type":"COMPLETED","achievements":[{"groupId":"FG000","numSubjects":"21"},{"groupId":"FG001","numSubjects":"26"}]},{"type":"NOT COMPLETED","achievements":[{"groupId":"FG000","numSubjects":"5"},{"groupId":"FG001","numSubjects":"8"}]}],"dropWithdraws":[{"type":"Adverse Event","reasons":[{"groupId":"FG000","numSubjects":"5"},{"groupId":"FG001","numSubjects":"8"}]}]}]},"baselineCharacteristicsModule":{"populationDescription":"Baseline characteristics were only recorded for patients who entered the study.","groups":[{"id":"BG000","title":"Revlimid 5mg/Day","description":"One 5 mg active Revlimid capsule and one 25 mg matched placebo capsule given by mouth daily in the morning (at ap