{"protocolSection":{"identificationModule":{"nctId":"NCT07707895","orgStudyIdInfo":{"id":"1438-0036"},"secondaryIdInfos":[{"id":"U1111-1334-0148","type":"REGISTRY","domain":"WHO International Clinical Trials Registry Platform (ICTRP)"},{"id":"2026-525634-27","type":"REGISTRY","domain":"CTIS"}],"organization":{"fullName":"Boehringer Ingelheim","class":"INDUSTRY"},"briefTitle":"DAREON®-36: A Study to Test Obrixtamig in Combination With ZL-1310 in People With Advanced Small Cell Lung Cancer or Other Neuroendocrine Cancers","officialTitle":"A Phase Ib/II, Open-label, Safety and Tolerability Trial of Obrixtamig in Combination With ZL-1310 in Patients With Poorly Differentiated NEC"},"statusModule":{"statusVerifiedDate":"2026-09","overallStatus":"NOT_YET_RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2026-10-19","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2030-04-26","type":"ESTIMATED"},"completionDateStruct":{"date":"2030-04-26","type":"ESTIMATED"},"studyFirstSubmitDate":"2026-07-13","studyFirstSubmitQcDate":"2026-07-13","studyFirstPostDateStruct":{"date":"2026-07-16","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-09-28","lastUpdatePostDateStruct":{"date":"2026-09-29","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Boehringer Ingelheim","class":"INDUSTRY"},"collaborators":[{"name":"Zai Lab","class":"UNKNOWN"}]},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":true,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This study is open to adults with advanced small cell lung cancer and other neuroendocrine cancers. The study has 2 parts. The purpose of Part 1 is to find a suitable dose of a combination study treatment, obrixtamig and ZL-1310. The purpose of Part 2 is to see how obrixtamig and ZL-1310 is tolerated when given with another medicine called a checkpoint inhibitor. Another purpose is to check whether the study treatment can stop the cancer from growing and keep it stable. Obrixtamig and ZL-1310 are being developed to help the immune system fight cancer.

In Part 1, participants get obrixtamig and ZL-1310. In Part 2, participants get obrixtamig and ZL-1310 with a checkpoint inhibitor. Part 2 is only open to people with advanced small cell lung cancer. All study treatments are given as infusions into a vein.

The study does not have a fixed duration. Participants can receive study treatment for up to 2 years if they benefit from treatment and can tolerate it. Participants visit the study site regularly, with some overnight stays required. During this time, doctors regularly check for health problems that could be caused by the study treatment. They also monitor the size of the tumour(s) and take laboratory tests."},"conditionsModule":{"conditions":["Small Cell Lung Cancer","Large Cell Neuroendocrine Lung Carcinoma","Extrapulmonary Neuroendocrine Carcinoma of Small Cell Histology","Extrapulmonary Neuroendocrine Carcinoma of Large Cell Histology"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE1","PHASE2"],"designInfo":{"allocation":"NON_RANDOMIZED","interventionModel":"SEQUENTIAL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":60,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Part 1: obrixtamig + ZL-1310 (dosing regimen 1)","type":"EXPERIMENTAL","interventionNames":["Drug: Obrixtamig","Drug: ZL-1310"]},{"label":"Part 1: obrixtamig + ZL-1310 (dosing regimen 2)","type":"EXPERIMENTAL","interventionNames":["Drug: Obrixtamig","Drug: ZL-1310"]},{"label":"Part 2: obrixtamig + ZL-1310 + atezolizumab","type":"EXPERIMENTAL","interventionNames":["Drug: Obrixtamig","Drug: ZL-1310","Drug: Atezolizumab"]}],"interventions":[{"type":"DRUG","name":"Obrixtamig","description":"Obrixtamig","armGroupLabels":["Part 1: obrixtamig + ZL-1310 (dosing regimen 1)","Part 1: obrixtamig + ZL-1310 (dosing regimen 2)","Part 2: obrixtamig + ZL-1310 + atezolizumab"]},{"type":"DRUG","name":"ZL-1310","description":"ZL-1310","armGroupLabels":["Part 1: obrixtamig + ZL-1310 (dosing regimen 1)","Part 1: obrixtamig + ZL-1310 (dosing regimen 2)","Part 2: obrixtamig + ZL-1310 + atezolizumab"]},{"type":"DRUG","name":"Atezolizumab","description":"Atezolizumab","armGroupLabels":["Part 2: obrixtamig + ZL-1310 + atezolizumab"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Part 1: The occurrence of dose limiting toxicities (DLTs) during the DLT evaluation period","timeFrame":"6 weeks from the first administration of study medication."},{"measure":"Part 2: The occurrence of treatment-emergent adverse events (AEs) leading to trial medication discontinuation or dose modification","timeFrame":"Up to 24 months."},{"measure":"Part 2: PFS rate at 6 months","description":"Progression-free survival (PFS) is defined as the time from first investigational medicinal product (IMP) administration until the earliest date of disease progression according to Response Evaluation Criteria In Solid Tumours (RECIST 1.1) based on investigator assessments or death from any cause, whichever occurs first.","timeFrame":"At 6 months."}],"secondaryOutcomes":[{"measure":"Part 1 and Part 2: Occurrence of treatment-emergent DLTs","timeFrame":"Up to 24 months."},{"measure":"Part 1 and Part 2: Occurrence of treatment-emergent adverse event of special interest (AESIs)","timeFrame":"Up to 24 months."},{"measure":"Part 1 and Part 2: Occurrence of treatment-emergent AEs CTCAE Grade ≥3","description":"AEs CTCAE = Adverse events Common Terminology Criteria for Adverse Events","timeFrame":"Up to 24 months."},{"measure":"Part 1 and Part 2: Objective response (OR)","description":"OR is defined as a best overall response of confirmed complete response (CR) or confirmed partial response (PR) according to RECIST 1.1 (based on investigator assessments) from the first IMP administration until the earliest date of disease progression, death, last evaluable tumour assessment before the start of the next line of anti-cancer treatment, loss to follow-up, or withdrawal of consent.","timeFrame":"Up to 24 months."},{"measure":"Part 1 and Part 2: Duration of response (DoR)","description":"DoR is defined as the time from the first documented objective response (OR) according to RECIST 1.1 until the earliest date of disease progression or death among patients with confirmed objective response based on investigator assessments.","timeFrame":"Up to 24 months."},{"measure":"Part 1 and Part 2: Disease control (DC)","description":"DC is defined as best overall response of complete response (CR) or partial response (PR) or stable disease (SD) where best overall response is defined according to RECIST version 1.1 based on investigator assessments from the first IMP administration until the earliest date of disease progression, death or last evaluable tumour assessment before start of the next line of anti-cancer treatment, loss to follow-up or withdrawal of consent.","timeFrame":"Up to 24 months."},{"measure":"Part 1: Progression-free survival (PFS)","description":"PFS is defined as the time from first IMP administration until the earliest date of disease progression according to RECIST 1.1 based on investigator assessments or death from any cause, whichever occurs first.","timeFrame":"Up to 24 months."},{"measure":"Part 2: Occurrence of DLTs during the DLT evaluation period","timeFrame":"6 weeks from the first administration of study medication."}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion criteria:

For Part 1

1. Diagnosed with locally advanced, metastatic or relapsed cancer of the following histologies:

   * Small cell lung carcinoma (SCLC)
   * Large cell neuroendocrine lung carcinoma (LCNEC-L)
   * Extrapulmonary neuroendocrine carcinoma (epNEC) of small or large cell histology
2. Patients with tumours with mixed histologies for any above type are eligible only if the neuroendocrine carcinoma/small cell component is predominant and represents at least 50% of the overall tumour tissue
3. Patients for whom no therapy of proven efficacy exists or who are not eligible for established treatment options. Patients must have exhausted available treatment options known to prolong survival for their disease. Previous therapies should include at least one line of platinum-based chemotherapy, unless there is a documented medical reason not to use platinum

   For Part 2
4. Histologically or cytologically confirmed extended stage small cell lung cancer (ES-SCLC) (excluding combined histologies) using the American Joint Committee on Cancer (AJCC) tumour node metastasis staging system combined with Veterans Administration Lung Study Group (VALG)'s two stage classification scheme.
5. Patients must have received no prior systemic therapy for ES-SCLC. Participants with prior chemoradiotherapy for Limited stage small cell lung cancer (LS-SCLC) must have been treated with curative intent and had a treatment-free interval of at least 6 months after the last chemotherapy, radiotherapy, or chemoradiotherapy before diagnosis of ES-SCLC to be eligible

   For both Part 1 and Part 2
6. Signed and dated written informed consent in accordance with International Council for Harmonisation of Technical Requirements for Pharmaceuticals for Human Use - Good Clinical Practice (ICH-GCP) and local legislation prior to any trial-specific procedures, sampling, or analyses
7. Male or female participants ≥18 years old and at least at the legal age of consent in countries where it is greater than 18 years at the time of signature of the informed consent form (ICF)
8. Willing and able to comply with scheduled visits, treatment schedule, the planned trial assessments, laboratory tests, restrictions regarding prohibited medications, lifestyle restrictions, and other requirements related to the trial. This includes that they are able to understand and follow trial-related instructions
9. Further inclusion criteria apply.

Exclusion criteria:

1. Serious concomitant disease or medical condition such as neurologic, psychiatric (including substance use disorder), active ulcers (gastrointestinal tract or skin) or laboratory abnormalities that may negatively impact patient safety during trial participation, affect compliance with trial requirements or invalidate assessments relevant for the investigation of the safety and preliminary efficacy of the investigational drugs
2. Patients with a diagnosis of Merkel cell carcinoma or medullary thyroid cancer
3. Presence of leptomeningeal disease and/or carcinomatous meningitis
4. Known hypersensitivity to the trial drugs or their excipients, prior severe, life-threatening hypersensitivity reaction(s) to monoclonal antibodies, or significant risk of allergic or anaphylactic reaction(s) to any of the investigated drug products according to the investigator's judgement
5. Participants who experienced severe, life-threatening immune-mediated adverse events, e.g. serious Grade 3 or higher immune-related adverse event (imAE) or infusion-related reactions, that led to permanent discontinuation while on treatment with immuno-oncology agents
6. Persistent toxicity from previous treatments that has not resolved to ≤ Common Terminology Criteria for Adverse Events (CTCAE) Grade 1 (except for alopecia, asthenia/fatigue, amenorrhea/menstrual disorders, CTCAE Grade 2 peripheral neuropathy, and CTCAE Grade 2 endocrinopathies controlled by replacement therapy, and toxicities, which are considered irreversible but stable for at least 4 weeks, per investigator judgment)
7. Therapy with any of the following types of treatments or drugs within the noted time intervals prior to IMP administration: At any time: treatment with delta-like ligand 3 (DLL3)-targeting therapies or received more than 30 Gy of thoracic radiotherapy.
8. Prior organ or tissue allograft
