.","armGroupLabels":["intervention group"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"The Health Belief Model Scale in Skin Cancer","description":"Developed by Dogan and Caydam (2021), the scale consists of 26 items and 5 sub-dimensions (perceived susceptibility, perceived benefit, perceived severity, perceived barriers, and self-efficacy). The HBMSSC is a five-point Likert-type scale, and each item is answered from "disagree=1" to "strongly agree=5". The total Cronbach's alpha coefficient of the scale is 0.86, and for the sub-dimensions it is 0.89; 0.79; 0.77; 0.65 and 0.86, respectively. The "perceived barriers" sub-dimension of the scale is reverse coded. The scale does not have a total score, and each sub-dimension is scored within itself. Higher "perceived susceptibility, "perceived benefit, "perceived severity", and "self-efficacy" scores indicate higher perceived susceptibility, perceived benefit, perceived severity, and self-efficacy","timeFrame":"One months"},{"measure":"The Health Belief Model Scale in Skin Cancer","description":"Developed by Dogan and Caydam (2021), the scale consists of 26 items and 5 sub-dimensions (perceived susceptibility, perceived benefit, perceived severity, perceived barriers, and self-efficacy). The HBMSSC is a five-point Likert-type scale, and each item is answered from "disagree=1" to "strongly agree=5". The total Cronbach's alpha coefficient of the scale is 0.86, and for the sub-dimensions it is 0.89; 0.79; 0.77; 0.65 and 0.86, respectively. The "perceived barriers" sub-dimension of the scale is reverse coded. The scale does not have a total score, and each sub-dimension is scored within itself. Higher "perceived susceptibility, "perceived benefit, "perceived severity", and "self-efficacy" scores indicate higher perceived susceptibility, perceived benefit, perceived severity, and self-efficacy","timeFrame":"Three months"},{"measure":"The Health Belief Model Scale in Skin Cancer","description":"Developed by Dogan and C