{"protocolSection":{"identificationModule":{"nctId":"NCT07413601","orgStudyIdInfo":{"id":"NCC5927"},"organization":{"fullName":"Cancer Institute and Hospital, Chinese Academy of Medical Sciences","class":"OTHER"},"briefTitle":"Phase 2 Clinical Study of Iparomlimab and Tuvonralimab (QL1706) in Combination With Platinum Chemotherapy Versus Platinum Chemotherapy in the Treatment of Second-/Third-line Triple Negative Breast Cancer (TNBC)","officialTitle":"Phase 2 Randomized Controlled Clinical Study of Iparomlimab and Tuvonralimab (QL1706) in Combination With Platinum Chemotherapy Versus Platinum Chemotherapy in the Treatment of Second-/Third-line Triple Negative Breast Cancer (TNBC)"},"statusModule":{"statusVerifiedDate":"2026-02","overallStatus":"NOT_YET_RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2026-02-10","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2029-02-10","type":"ESTIMATED"},"completionDateStruct":{"date":"2029-02-10","type":"ESTIMATED"},"studyFirstSubmitDate":"2026-02-03","studyFirstSubmitQcDate":"2026-02-09","studyFirstPostDateStruct":{"date":"2026-02-17","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-02-09","lastUpdatePostDateStruct":{"date":"2026-02-17","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"PRINCIPAL_INVESTIGATOR","investigatorFullName":"Ma Fei，MD","investigatorTitle":"Chief Physician","investigatorAffiliation":"Cancer Institute and Hospital, Chinese Academy of Medical Sciences"},"leadSponsor":{"name":"Cancer Institute and Hospital, Chinese Academy of Medical Sciences","class":"OTHER"}},"oversightModule":{"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This study is an open-label, prospective, phase 2, randomized controlled study to evaluate the efficacy and safety of apolitovorrelizumab (QL1706) in combination with platinum chemotherapy versus platinum chemotherapy in the treatment of advanced unresectable and or metastatic triple negative breast cancer previously treated with first-line or second-line systems. It is planned to enroll 78 subjects in this study. Subjects who meet the inclusion and exclusion criteria are divided into a random ratio of 1:1. The experimental group will receive QL1706 in combination with platinum chemotherapy selected by the investigator, and the control group will receive platinum chemotherapy selected by the investigator. A treatment cycle will be held every 3 weeks until disease progression or intolerable toxicity occurs. After subjects in the control group withdraw from the study, they are allowed to receive other treatments selected by the QL1706 co-investigators based on the subjects 'wishes. Efficacy assessments will be conducted every 6 weeks (42 days ±7 days) after treatment until disease progression, withdrawal of informed consent, death, or start of new antitumor therapy, whichever comes first."},"conditionsModule":{"conditions":["Triple Negative Breast Cancer Metastatic"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE2"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":78,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Experimental","type":"EXPERIMENTAL","interventionNames":["Drug: QL1706","Drug: Cisplatin/ Carboplatin"]},{"label":"Control Group","type":"EXPERIMENTAL","interventionNames":["Drug: Cisplatin/ Carboplatin"]}],"interventions":[{"type":"DRUG","name":"QL1706","description":"IV infusion, 5mg/kg, given every 3 weeks, every 3 weeks as a cycle；","armGroupLabels":["Experimental"]},{"type":"DRUG","name":"Cisplatin/ Carboplatin","description":"Cisplatin: 75mg/m2, intravenous infusion, Day 1 (or divided into 3 days), every 3 weeks as cycles; carboplatin: AUC5, intravenous infusion, Day 1, every 3 weeks as cycles;","armGroupLabels":["Control Group","Experimental"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Median Progression-Free Survival (PFS)","description":"The time interval between the start of study drug use and the patient's disease progression or death.","timeFrame":"From date of randomization until the date of first documented progression or date of death from any cause, whichever came first, assessed up to 36 months"}],"secondaryOutcomes":[{"measure":"objective response rate（ORR）","description":"Proportion of patients with complete response (CR) and partial response (PR) assessed according to RECIST 1.1 in solid tumors","timeFrame":"assessed up to 36 months"},{"measure":"disease control rate（DCR）","description":"Proportion of patients with complete response, partial response, and stable response as assessed according to RECIST 1.1 in solid tumors.","timeFrame":"assessed up to 36 months"},{"measure":"duration of response","description":"Time from the start of complete response (CR) or partial response (PR) on the first tumor assessment to progression of disease (PD) or death from any cause on the first tumor assessment","timeFrame":"assessed up to 36 months"},{"measure":"overall survival（OS）","description":"Time from start of study drug to death from any cause","timeFrame":"assessed up to 36 months"},{"measure":"adverse events","description":"Incidence of adverse events (AEs), serious adverse events (SAEs), treatment-related adverse events (TRAEs), immune-related adverse events (irAEs)","timeFrame":"assessed up to 36 months"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Age ≥18 years, regardless of gender;
* ECOG performance status: 0-1;
* Locally advanced or metastatic triple negative breast cancer confirmed by histopathology that is not suitable for curative treatment and cannot be treated surgically (Defined as negative for HER2, ER and PR expression according to the latest ASCO/CAP guidelines);
* Patients who have previously received first-line or second-line systemic treatment for locally advanced or metastatic breast cancer and have experienced recurrence within 12 months after the end of previous adjuvant therapy are counted as first-line systemic therapy;
* There is radiographic or objective evidence of disease progression at the last systemic treatment before or after the start of study treatment;
* Patients have at least one evaluable lesion (based on CT or MRI according to the RECIST 1.1 criteria);
* Tissue or blood samples for biomarker testing can be provided, tissue samples during the baseline period (try to provide tumor puncture tissue after recent progression, if not, previously archived tissue is also available, 5-10 white slides); blood samples during the baseline period, after 2 cycles of treatment and after progression;
* Good organ function：The bone marrow function must be tested within 14 days before enrollment, white blood cell count (WBC) ≥3.5×109/L, hemoglobin (Hb) ≥90g/L, absolute neutrophil count (ANC) ≥1.5×109/L, and platelets (PLT) ≥80×109/L, and have not received blood transfusion or biological response modifiers (such as granulocytes, erythrocyte growth factor, Shengxuebao, etc.) within 14 days before the first dose. Liver function: Liver function must be tested within 14 years before enrollment. Patients without liver metastasis require serum total bilirubin (TBIL) ≤1.5× upper limit of normal (ULN); alanine aminotransferase (ALT) and aspartate aminotransferase (AST) ≤2.5×ULN. Requirements for patients with liver metastases: serum total bilirubin (TBIL) ≤1.5× the upper limit of normal (ULN); alanine aminotransferase (ALT) and aspartate aminotransferase (AST) ≤5×ULN; alkaline phosphatase (ALP) ≤5×ULN in patients with liver metastases and no bone metastases, and ALP≤2.5×ULN in patients without liver and bone metastases. Renal function: Renal function should be tested within 14 days before enrollment, with blood creatinine ≤1.5×ULN or creatinine clearance ≥60mL/min (based on the Cockcroft-Gault formula). No serious cardiac dysfunction, left ventricular ejection fraction (LVEF) ≥50%(confirmed by ECHO) .Coagulation function: International normalized ratio (INR) ≤1.5×ULN and activated partial thromboplastin time (APTT) ≤1.5×ULN (unless receiving the\*utic anticoagulant drugs).
* Patients of childbearing potential must use effective contraceptive measures during the study until 6 months after the last dose.
* The patient voluntarily joined the study and signed the informed consent form, with good compliance.

Exclusion Criteria:

* Previous use of CTLA-4 monoclonal antibody or PD-1/PD-L1 and CTLA-4 bispecific antibodies (such as cardonilumab, KN046, etc.) or bifunctional combination antibodies (e.g., apolitto vorrelizumab);
* relapse within 6 months after the end of previous (new) adjuvant immune checkpoint inhibitor therapy; or progression-free survival of locally advanced or metastatic breast cancer receiving immune checkpoint inhibitor therapy; 6 months;
* relapse within 6 months after the end of previous (new) adjuvant platinum therapy; Or locally advanced or metastatic breast cancer receiving platinum therapy has a progression-free survival of \<3 months (if the drug is discontinued due to non-tumor progression factors, but the duration of discontinuation is ≥3 months before randomization, you can participate in this study);
* Those who have experienced immune-related toxicity that led to permanent drug discontinuation during previous anti-tumor immunotherapy, or have experienced immune-related adverse events (irAEs) of ≥ grade 3 or immune-related myocarditis of ≥ grade 2 and are assessed by the investigator as not suitable for treatment in this study. Grade 3 endocrine abnormalities with stable control of hormone replacement therapy can be enrolled after the investigator assessed that these irAEs will not affect the administration of study drugs and safety assessment;
* Previous history of or concurrent interstitial pneumonia, severe chronic obstructive pulmonary disease, severe pulmonary dysfunction, symptomatic bronchospasm, etc.;
* Previous history of other primary malignant tumors; Note: Except for basal cell carcinoma of the skin, superficial bladder cancer, squamous cell carcinoma of the skin, or cervical cancer in situ; Or patients who have received radical treatment and have not relapsed within 5 years of treatment can participate in this trial;
* Have experienced severe allergic reactions to the pharmaceutical or inactive ingredients of the study drug;
* Adverse reactions from previous anti-tumor therapy have not recovered to NCI-CTCAE 5.0 grade evaluation ≤1 (Except for toxicities that are judged by the investigator to have no safety risks, such as hair loss);
* Have active autoimmune disease or have a history of autoimmune disease, are using immunosuppressants, or systemic hormone therapy (prednisone or other equivalent hormone at a dose\>10mg/day), and continue to use it within 2 weeks prior to enrollment. Except for the following diseases: Clinically stable autoimmune thyroid disease; Type 1 diabetes treated with hormone replacement therapy; through local treatment (e.g., low-dose topical hormones) are well controlled and no autoimmune skin diseases requiring additional treatment due to acute exacerbation within 12 months prior to screening (such as eczema, psoriasis, chronic lichen simplex, or vitiligo with simple skin lesions accumulating less than 10% of the body surface area);
* Any serious or uncontrollable systemic disease, including hypertension that is not well controlled with drugs, according to the investigator's judgment (systolic blood pressure\>160mmHg or diastolic blood pressure\>100mmHg), uncontrolled diabetes, and signs of active bleeding, etc.;
* Uncontrolled cardiac disease, including heart failure of NYHA class 2 or above, unstable angina pectoris, myocardial infarction within 1 year, clinically significant supraventricular or ventricular arrhythmia requiring treatment, prolonged QT syndrome, such as QTc\>450ms (men) or QTc\>470ms (women);
* Evidence of active infection includes but is not limited to hepatitis B (both HBsAg positive and HBVDNA≥2000IU/mL, and hepatitis caused by drugs or other reasons is excluded), hepatitis C (both anti-HCV antibody positive and HCV RNA positive) or human immunodeficiency virus (HIV) infection;
* Women with positive serum pregnancy tests or nursing do not agree to use adequate contraceptive measures during the study and for 6 months after receiving the trial drug;
* Subjects with known central nervous system metastases and/or cancerous meningitis (except for: asymptomatic, or treatment-treated and stable, no new brain metastases or radiographic evidence of expansion of brain metastases has been found for at least 4 weeks after treatment for brain metastases, and steroid or anticonvulsant treatment has been discontinued for at least 14 days before the start of study treatment);
* Other circumstances that the investigator deems unsuitable for participation in this clinical trial.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"centralContacts":[{"name":"MFei","role":"CONTACT","phone":"+86 13710217780","email":"mafei2011@139.com"}],"locations":[{"facility":"No. 17 Panjiayuan Nan Li, Chaoyang District, Beijing","city":"Beijing","state":"Beijing Municipality","zip":"100021","country":"China","geoPoint":{"lat":39.9075,"lon":116.39723}}]}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-10-01"},"conditionBrowseModule":{"meshes":[{"id":"D064726","term":"Triple Negative Breast Neoplasms"}],"ancestors":[{"id":"D001943","term":"Breast Neoplasms"},{"id":"D009371","term":"Neoplasms by Site"},{"id":"D009369","term":"Neoplasms"},{"id":"D001941","term":"Breast Diseases"},{"id":"D012871","term":"Skin Diseases"},{"id":"D017437","term":"Skin and Connective Tissue Diseases"}]},"interventionBrowseModule":{"meshes":[{"id":"D002945","term":"Cisplatin"},{"id":"D016190","term":"Carboplatin"}],"ancestors":[{"id":"D017606","term":"Chlorine Compounds"},{"id":"D007287","term":"Inorganic Chemicals"},{"id":"D017672","term":"Nitrogen Compounds"},{"id":"D017671","term":"Platinum Compounds"},{"id":"D056831","term":"Coordination Complexes"},{"id":"D009930","term":"Organic Chemicals"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT05024812","orgStudyIdInfo":{"id":"HMPL-013-FLAG-G102"},"organization":{"fullName":"The First Affiliated Hospital of Zhengzhou University","class":"OTHER"},"briefTitle":"Fruquintinib Combined With Toripalimab and SOX Regimen in the First-line Treatment of Advanced Metastatic Gastric or Gastroesophageal Junction Adenocarcinoma","officialTitle":"An Open Label, Single Arm, Multicenter Phase Ⅰb/Ⅱ Clinical Study of Fruquintinib Combined With Toripalimab and SOX Regimen in the First-line Treatment of Advanced Metastatic Gastric or Gastroesophageal Junction Adenocarcinoma"},"statusModule":{"statusVerifiedDate":"2022-08","overallStatus":"UNKNOWN","lastKnownStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2022-06-01","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2023-08","type":"ESTIMATED"},"completionDateStruct":{"date":"2025-02","type":"ESTIMATED"},"studyFirstSubmitDate":"2021-08-20","studyFirstSubmitQcDate":"2021-08-25","studyFirstPostDateStruct":{"date":"2021-08-27","type":"ACTUAL"},"lastUpdateSubmitDate":"2022-08-17","lastUpdatePostDateStruct":{"date":"2022-08-18","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"PRINCIPAL_INVESTIGATOR","investigatorFullName":"Feng Wang","investigatorTitle":"Professor","investigatorAffiliation":"The First Affiliated Hospital of Zhengzhou University"},"leadSponsor":{"name":"The First Affiliated Hospital of Zhengzhou University","class":"OTHER"}},"oversightModule":{"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This is a prospective, open-label, multicenter, single arm phase Ⅰb/Ⅱ clinical study aims to explore the efficacy and safety of fruquintinib combined with toripalimab and SOX regimen in the first-line treatment of unresectable advanced metastatic gastric or gastroesophageal junction adenocarcinoma.","detailedDescription":"At present, the first-line standard treatment of metastatic gastric cancer is still doublet or triplet chemotherapy of fluorouracil combined with platinum or paclitaxel. In recent years, immune checkpoint inhibitors (ICIs) have emerged in advanced gastric cancer with their unique mechanism of action. PD-1 monoclonal antibody has been explored in multiple combination schemes in the first-line treatment of advanced gastric cancer. This study aims to explore the efficacy and safety of an antiangiogenetic TKI, fruquintinib combined with an ICI, toripalimab and the standard doublet SOX regimen in the first-line treatment of unresectable advanced metastatic gastric or gastroesophageal junction adenocarcinoma."},"conditionsModule":{"conditions":["Metastatic Gastric Cancer"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE1","PHASE2"],"designInfo":{"allocation":"NA","interventionModel":"SINGLE_GROUP","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":64,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Experimental","type":"EXPERIMENTAL","description":"fruquintinib + toripalimab + SOX","interventionNames":["Drug: fruquintinib＋toripalimab + SOX"]}],"interventions":[{"type":"DRUG","name":"fruquintinib＋toripalimab + SOX","description":"phase Ib: fruquintinib (dose finding): L1: 3 mg/d，L2: 4 mg/d，L3: 5 mg/d, qd po, D1-14, Q3W toripalimab: 240mg, I.V., D1, Q3W; S-1: 40-60mg bid, D1-14, Q3W; Oxaliplatin: 130mg/m\^2, ivgtt 2h, D1,Q3W. phase II: fruquintinib: RP2D toripalimab: 240mg, I.V., D1, Q3W; S-1: 40-60mg bid, D1-14, Q3W; Oxaliplatin: 130mg/m\^2, ivgtt 2h, D1,Q3W.","armGroupLabels":["Experimental"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"DLTs","description":"DLTs are defined as grade 3 or higher adverse events that are related to fruquintinib during the first cycle of therapy.","timeFrame":"At the end of Cycle 1 (each cycle is 28 days)"},{"measure":"RP2D","description":"Maximum tolerated dose (MTD) and recommended Phase 2 dose (RP2D)","timeFrame":"At the end of Cycle 1 (each cycle is 28 days)"},{"measure":"PFS","description":"PFS was defined as the time from randomization to the first documented progressive disease (PD) or death due to any cause, whichever occurred first.","timeFrame":"about 2 years"}],"secondaryOutcomes":[{"measure":"OS","description":"The time from treatment initiation until death from any reason","timeFrame":"about 2 years"},{"measure":"ORR","description":"The proportion of patients with a confirmed complete response or partial response on two consecutive occasions≥4 weeks apart","timeFrame":"about 2 years"},{"measure":"DCR","description":"The proportion of patients with a best overall response of confirmed complete or partial response, or stable disease (CR+ PR + SD)","timeFrame":"about 2 years"},{"measure":"DoR","description":"Duration of Response is defined as the time from the first documentation of response (PR or better) to the first documented disease progression evidence (according to RECIST 1.1) of the responders","timeFrame":"about 2 years"},{"measure":"adverse events (AEs) categorized by severity in accordance with the NCI CTC AE Version 5.0","description":"Safety and tolerance will be evaluated by incidence, severity and outcomes of adverse events (AEs) and categorized by severity in accordance with the NCI CTC AE Version 5.0","timeFrame":"about 2 years"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Pathologically determined unresectable advanced gastric or gastroesophageal junction adenocarcinoma;
* 18-75 years old (including 18 and 75 years old);
* No previous anti-tumor treatment for metastatic diseases;
* HER2 negative;
* Eastern Cooperation Oncology Group (ECOG) performance status of 0-1;
* Life expectancy ≥ 3 months;
* At least one measurable lesion according to RECIST version 1.1;
* Adequate organ and bone marrow functions:

Absolute neutrophil count≥1.5x10\^9/L; Platelet count≥100x10\^9/L; Hemoglobin≥9g/dL; Serum bilirubin≤1.5x the upper limit of normal(ULN); Alanine aminotransferase(ALT) and aspartate aminotransferase(AST)≤1.5x ULN; Serum creatinine≤1.5x ULN; Endogenous creatinine clearance rate ≥ 50ml / min;

* Women of childbearing age need to take effective contraceptive measures.

Exclusion Criteria:

* Previous treatment with vascular endothelial growth factor receptor (VEGFR) inhibitors or previous use of immune checkpoint inhibitors;
* Other malignant tumors in the past 5 years, except for skin basal cell or squamous cell carcinoma after radical surgery, or cervical carcinoma in situ;
* There was central nervous system (CNS) metastasis or previous brain metastasis before enrollment;
* Patients with autoimmune diseases or history of autoimmune diseases within 4 weeks before enrollment;
* Previously received allogeneic bone marrow transplantation or organ transplantation;
* Uncontrolled malignant ascites;
* Participated in other unapproved or unlisted drug clinical trials in China within 4 weeks before enrollment, and received corresponding experimental drug treatment;
* Cardiovascular disease, including unstable angina or myocardial infarction, occurred within 6 months before the start of study treatment;
* Subjects allergic to the study drug or any of its adjuvants;
* International normalized ratio (INR) \> 1.5 or partially activated prothrombin time (APTT) \> 1.5 × ULN；
* The researchers judged clinically significant electrolyte abnormalities;
* At present, the patient has hypertension that cannot be controlled by drugs, which is specified as: systolic blood pressure ≥ 140 mmHg and / or diastolic blood pressure ≥ 90 mmHg;
* Patients currently have poorly controlled diabetes (fasting glucose level is greater than CTCAE grade 2 after regular treatment);
* Patients with dysphagia, active peptic ulcer, intestinal obstruction, active gastrointestinal bleeding, peptic perforation, malabsorption syndrome or uncontrolled intestinal inflammatory diseases;
* Any disease or state affecting drug absorption before enrollment, or the patient cannot take oral medication;
* Patients with obvious evidence of bleeding tendency or medical history within 3 months before enrollment, hemoptysis or thromboembolism within 12 months;
* Cardiovascular diseases with significant clinical significance, including but not limited to acute myocardial infarction, severe / unstable angina pectoris or coronary artery bypass grafting within 6 months before enrollment;
* Ventricular arrhythmia requiring drug treatment;
* Congestive heart failure ≤New York Heart Association (NYHA) class 2;
* LVEF \< 50%;
* Active or uncontrolled severe infection ≥ grade 2 according to National Cancer Institute Common Toxicity (NCI-CTC) criteria;
* With positive urine protein and 24-hour urinary protein content\>1g;
* Known human immunodeficiency virus (HIV) infection; known history of clinically significant liver disease, including viral hepatitis;
* Pregnant (positive pregnancy test before medication) or lactating women;
* Complications require long-term immunosuppressive treatment, or systemic or local use of immunosuppressive corticosteroids (\> 10mg / day prednisone or other therapeutic hormones);
* By judgment of the investigator, there are concomitant diseases that seriously endanger the safety of the patient or affect the completion of the study.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","maximumAge":"75 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"centralContacts":[{"name":"Feng Wang, M.D.","role":"CONTACT","phone":"860013938244776","email":"fengw010@163.com"},{"name":"Qingxia Fan, M.D.","role":"CONTACT"}],"locations":[{"facility":"The First Affiliated Hospital of Zhengzhou University","status":"RECRUITING","city":"Zhengzhou","state":"Henan","zip":"450052","country":"China","contacts":[{"name":"Feng Wang, doctor","role":"CONTACT"},{"name":"Qingxia Fan, doctor","role":"CONTACT"}],"geoPoint":{"lat":34.75778,"lon":113.64861}}]},"ipdSharingStatementModule":{"ipdSharing":"NO"}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-10-01"},"conditionBrowseModule":{"meshes":[{"id":"D013274","term":"Stomach Neoplasms"}],"ancestors":[{"id":"D005770","term":"Gastrointestinal Neoplasms"},{"id":"D004067","term":"Digestive System Neoplasms"},{"id":"D009371","term":"Neoplasms by Site"},{"id":"D009369","term":"Neoplasms"},{"id":"D004066","term":"Digestive System Diseases"},{"id":"D005767","term":"Gastrointestinal Diseases"},{"id":"D013272","term":"Stomach Diseases"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT01288612","orgStudyIdInfo":{"id":"10-007787"},"secondaryIdInfos":[{"id":"RC4DK090413","type":"NIH","link":"https://reporter.nih.gov/quickSearch/RC4DK090413"},{"id":"UL1TR000135","type":"NIH","link":"https://reporter.nih.gov/quickSearch/UL1TR000135"}],"organization":{"fullName":"Mayo Clinic","class":"OTHER"},"briefTitle":"Comparative Effectiveness of Endoscopic Assessment of Gastroesophageal Reflux and Barretts Esophagus","officialTitle":"Comparative Effectiveness of Endoscopic Assessment of Gastroesophageal Reflux and Barretts Esophagus","acronym":"challenge"},"statusModule":{"statusVerifiedDate":"2014-12","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2011-02"},"primaryCompletionDateStruct":{"date":"2013-10","type":"ACTUAL"},"completionDateStruct":{"date":"2013-10","type":"ACTUAL"},"studyFirstSubmitDate":"2011-01-28","studyFirstSubmitQcDate":"2011-02-01","studyFirstPostDateStruct":{"date":"2011-02-02","type":"ESTIMATED"},"resultsFirstSubmitDate":"2014-12-23","resultsFirstSubmitQcDate":"2014-12-23","resultsFirstPostDateStruct":{"date":"2015-01-07","type":"ESTIMATED"},"lastUpdateSubmitDate":"2014-12-23","lastUpdatePostDateStruct":{"date":"2015-01-07","type":"ESTIMATED"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"PRINCIPAL_INVESTIGATOR","investigatorFullName":"Prasad G. Iyer","investigatorTitle":"MD","investigatorAffiliation":"Mayo Clinic"},"leadSponsor":{"name":"Mayo Clinic","class":"OTHER"},"collaborators":[{"name":"National Institute of Diabetes and Digestive and Kidney Diseases (NIDDK)","class":"NIH"},{"name":"National Center for Advancing Translational Sciences (NCATS)","class":"NIH"},{"name":"American College of Gastroenterology","class":"OTHER"}]},"oversightModule":{"oversightHasDmc":false},"descriptionModule":{"briefSummary":"The hypothesis of this study was that the comparative effectiveness of unsedated transnasal endoscopy (uTNE) will be greater than sedated endoscopy (sEGD) in population screening for BE.","detailedDescription":"Barrett's esophagus (BE), a well-known complication of Gastroesophageal Reflux (GER), is the strongest known precursor of esophageal adenocarcinoma. Thus, identifying effective screening approaches for the early detection of BE are highly desired. Current impediments to BE screening include 1) the inability to utilize sedated endoscopy (sEGD) effectively in populations and 2) current GER-based paradigms for detecting BE. Referral center studies demonstrate comparable accuracy between unsedated transnasal endoscopy (uTNE) and sEGD. However, patient acceptability and diagnostic yield with uTNE in general populations remain unknown.

Using the Rochester, Minnesota Epidemiology Project resources, random samples of Olmsted County residents were drawn, and those subjects were mailed validated gastrointestinal symptom questionnaires. These surveys allowed identification of a cohort of community subjects well characterized by the frequency of reflux symptoms. Eligible subjects who were greater than or equal to 50 years old, and who had no previous history of endoscopic evaluation and who were not known to have BE were randomized, stratified by age, sex, and reflux symptoms, and assigned to one of the 3 arms of the study. Subjects in each arm who met the eligibility criteria were initially sent generic invitation letters asking if they agreed to be contacted by phone in two weeks' time to inform them about a research study. If potential subjects explicitly declined to be contacted they were excluded from the study. Eligible subjects were contacted by telephone and only offered the endoscopy technique they had been randomized to. Subjects who accepted and signed an informed consent document were treated according to their randomized assignment and all 3 groups were followed up in the same manner.

Biopsies were taken from any endoscopically suspected BE and from the gastroesophageal junction and squamous mucosa in all subjects. The length of BE segment was defined using Prague criteria. All participants received a telephone call from the research coordinator 1 and 30 days after the procedure to complete validated tolerability scales and adverse events questionnaires."},"conditionsModule":{"conditions":["Barrett's Esophagus"],"keywords":["Barrett's Esophagus"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"SCREENING","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":459,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Sedated Endoscopy","type":"ACTIVE_COMPARATOR","description":"Sedated esophagogastroduodenoscopy with biopsy","interventionNames":["Device: Sedated Endoscopy"]},{"label":"Transnasal Endoscopy at Hospital Unit","type":"ACTIVE_COMPARATOR","description":"Unsedated transnasal endoscopy at hospital unit.","interventionNames":["Device: Transnasal Endoscopy"]},{"label":"Transnasal Endoscopy at Mobile Unit","type":"ACTIVE_COMPARATOR","description":"Unsedated transnasal endoscopy in mobile research van","interventionNames":["Device: Transnasal Endoscopy"]}],"interventions":[{"type":"DEVICE","name":"Sedated Endoscopy","description":"The sedated esophagogastroduodenoscopy procedures were performed using a conventional high-definition endoscope (GIF-180, Olympus America, Center Valley, Pennsylvania) under conscious sedation with intravenous midazolam and fentanyl.","armGroupLabels":["Sedated Endoscopy"]},{"type":"DEVICE","name":"Transnasal Endoscopy","description":"Unsedated transnasal endoscopy performed using the EndoSheath transnasal esophagoscope (TNL-5000, Vision Sciences). Topical anesthetic aerosol spray was applied to the posterior pharynx and nasal spray mixture was applied to the patients nares 10-15 minutes before the endoscopy procedure.","armGroupLabels":["Transnasal Endoscopy at Hospital Unit","Transnasal Endoscopy at Mobile Unit"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Percentage of Subjects Who Agreed to Participated in the Esophageal Assessment","description":"This outcome measure was defined as the proportion of subjects who agreed to undergo esophageal assessment in the three groups out of those who were eligible to be contacted for participation in screening.","timeFrame":"Approximately 2 weeks after invitation letter was sent"}],"secondaryOutcomes":[{"measure":"Rate of Successful Intubation","description":"The rate of successful intubation was defined as the ability to traverse the upper esophageal sphincter and visualize the esophageal mucosa and classified as successful or unsuccessful.","timeFrame":"Visit 1"},{"measure":"Rate of Complete Evaluation","description":"The rate of complete evaluation was defined as visualization of the whole esophagus and identification of landmarks: squamocolumnar junction, gastroesophageal junction (upper margin of gastric folds with stomach deflated), and the diaphragmatic hiatus. The categories of evaluation were classified as complete (all three landmarks identified), incomplete (some landmarks identified), or unsuccessful.","timeFrame":"Visit 1"},{"measure":"Rate of Acquisition of Biopsies From the Esophagus","timeFrame":"Visit 1"},{"measure":"Mean Duration of Procedure","description":"Duration of the procedure was defined as time from the beginning of the procedure (initiation of sedation or local anesthesia) to extubation.","timeFrame":"Visit 1"},{"measure":"Mean Time From Extubation to Discharge","description":"This outcome measures the recovery time after the procedure.","timeFrame":"Visit 1"},{"measure":"Mean Tolerability Scores","description":"Validated pain scales (where 0 is none and 10 is severe) were used to assess the degree of pain, choking, gagging, and anxiety experienced during the procedure. Overall tolerance was rated on a scale from 0 to 10, where 0 is good, and 10 is poor tolerance.","timeFrame":"Day 1 after the procedure"},{"measure":"Acceptability","description":"Acceptability was defined as the proportion of subjects willing to undergo the procedure again in the future.","timeFrame":"Day 1 after the procedure"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

