{"protocolSection":{"identificationModule":{"nctId":"NCT02735928","orgStudyIdInfo":{"id":"PARROT"},"organization":{"fullName":"Catholic University of the Sacred Heart","class":"OTHER"},"briefTitle":"Pressurized Intraperitoneal Aerosol Chemotherapy (PIPAC) Applied to Platinum-Resistant Recurrence of Ovarian Tumor","officialTitle":"Feasibility, Efficacy and Safety of Pressurized Intraperitoneal Aerosol Chemotherapy (PIPAC) With Cisplatin in Women With Recurrent Ovarian Cancer: an Open-label, Single-arm Phase I-II Clinical Trial","acronym":"PARROT"},"statusModule":{"statusVerifiedDate":"2023-11","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2016-01","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2021-06-15","type":"ACTUAL"},"completionDateStruct":{"date":"2022-06-16","type":"ACTUAL"},"studyFirstSubmitDate":"2016-02-08","studyFirstSubmitQcDate":"2016-04-07","studyFirstPostDateStruct":{"date":"2016-04-13","type":"ESTIMATED"},"lastUpdateSubmitDate":"2023-11-13","lastUpdatePostDateStruct":{"date":"2023-11-15","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"PRINCIPAL_INVESTIGATOR","investigatorFullName":"Prof. Giovanni Scambia","investigatorTitle":"Professor","investigatorAffiliation":"Catholic University of the Sacred Heart"},"leadSponsor":{"name":"Catholic University of the Sacred Heart","class":"OTHER"}},"oversightModule":{"oversightHasDmc":false},"descriptionModule":{"briefSummary":"Patients with first recurrent resistance ovarian cancer and disease progression with peritoneal carcinomatosis will undergo PIPAC procedure. The primary end point is to determine the clinical benefit rate (CBR) of a pressurized intraperitoneal aerosol chemotherapy with a combination of cisplatin and doxorubicin.","detailedDescription":"This study aims to investigate the therapeutic efficacy of PIPAC using cisplatin and doxorubicin in women with first recurrent resistance ovarian cancer and disease progression with peritoneal carcinomatosis. The primary objective of this study is to determine the Clinical Benefit Rate (CBR) according to RECIST/GCOG criteria after three cycles of PIPAC with PIPAC cisplatin and doxorubicin"},"conditionsModule":{"conditions":["Ovarian Epithelial Cancer Recurrent","Platinum-resistant"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"NA","interventionModel":"SINGLE_GROUP","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":40,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"PIPAC","type":"EXPERIMENTAL","description":"PIPAC stands for Pressurized IntraPeritoneal Aerosol Chemotherapies. Enrolled patients will undergo to explorative laparoscopy as usual and PC index will be determined according to Fagotti score (PIV). Pathological response will be determined by serial peritoneal biopsies. Then a pressurized aerosol containing cisplatin followed by doxorubicin will be applied via a nebulizer. The PIPAC procedure can be repeated after 4-6 weeks until progression or limiting toxicity","interventionNames":["Device: Pressurized intraperitoneal aerosol chemotherapy with cisplatin and doxorubicin"]}],"interventions":[{"type":"DEVICE","name":"Pressurized intraperitoneal aerosol chemotherapy with cisplatin and doxorubicin","description":"After insufflation of a 12 mmHg of capnoperitoneum at 37 °C, two balloon trocars will be placed. Parietal biopsies will be taken and ascites (\< 500cc) will be removed. A nebulizer will be connected to a high-pressure injector and will be inserted into the abdomen through a trocar. A pressurized aerosol containing cisplatin at a dose of 10.5 mg/m2 body surface in 150 ml NaCl 0.9 % followed by doxorubicin at a dose of 2.1 mg/m2 body surface in a 50 ml NaCl 0.9% solution will be applied via a nebulizer immediately. Then, the system will be kept in steady-state for 30 min (i.e.: application time).","armGroupLabels":["PIPAC"],"otherNames":["PIPAC"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Clinical Benefit Rate (CBR) according to RECIST/GCOG criteria after three cycles of PIPAC with PIPAC cisplatin and doxorubicin","description":"Evaluation of target lesions will be done as follows:

* Complete Response (CR): Disappearance of all target lesions. Any pathological lymph nodes (whether target or non-target) must have reduction in short axis to \<10 mm.
* Partial Response (PR): At least a 30% decrease in the sum of diameters of target lesions, taking as reference the baseline sum diameters.
* Progressive Disease (PD): At least a 20% increase in the sum of diameters of target lesions, taking as reference the smallest sum on study (this includes the baseline sum if that is the smallest on study). In addition to the relative increase","timeFrame":"12-18 weeks"}],"secondaryOutcomes":[{"measure":"The median time to progression according to RECIST criteria after three cycles of PIPAC with cisplatin","description":"From the last chemotherapy cycle to the first clinical-radiological signs of disease relapse","timeFrame":"1 Year"},{"measure":"Fagotti score, as assessed by laparoscopy","timeFrame":"1 Year"},{"measure":"The degree of histological regression assessed by pathological review of repeated peritoneal biopsies","timeFrame":"1 Year"},{"measure":"The proportion of women with a reduction of serum CA-125 of at least 50% after PIPAC","timeFrame":"1 Year"},{"measure":"Evaluation of the Quality Of Life (QOL) on the basis of the European Organization for Research and Treatment of Cancer (EORTC) QOL questionnaires","description":"Quality of life will be assess using the EORTC quality of life questionnaire core-36 (QLQC-30) and the ovarian cancer-specific quality of life questionnaire (QLQ-Ov28).These will be complete before and after the first, second, and third PIPAC applications","timeFrame":"1 year"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Patients affected by first or second platinum resistant epithelial ovarian tumor recurrence.
* ECOG-performance status ≤ 3.
* Adequate respiratory, hepatic, cardiac, kidney and bone marrow function (absolute neutrophil count \> 1500 / mm3, platelets \> 150 000/μl, creatinine clearance \> 60 mL / min according to Cockroft formula).
* Patient-compliant and psychologically able to follow the trial procedures.

Exclusion Criteria:

* Non-epithelial ovarian cancer or borderline ovarian tumor.
* Pregnancy or breastfeeding.
* Patients affected by major depressive disorder even in treatment or minor mood disorders.
* Patients with severe impairment of respiratory, hepatic or renal function.
* Patients with cardiac, neurological or metabolic uncontrolled pharmacologically disease
* Patients with bowel obstruction.
* Inadequate bone marrow, liver, kidney function.
* No clear-peritoneal disease at surgical exploration.
* Patients with ascites \>2000 cc (CT-Scan)
* Patients who have already made third line chemotherapy.","healthyVolunteers":false,"sex":"FEMALE","minimumAge":"18 Years","maximumAge":"70 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"locations":[{"facility":"Catholic University of Sacred Heart","city":"Rome","zip":"00168","country":"Italy","geoPoint":{"lat":41.89193,"lon":12.51133}}]},"referencesModule":{"references":[{"pmid":"24378877","type":"RESULT","citation":"Fagotti A, Petrillo M, Costantini B, Fanfani F, Gallotta V, Chiantera V, Turco LC, Bottoni C, Scambia G. Minimally invasive secondary cytoreduction plus HIPEC for recurrent ovarian cancer: a case series. Gynecol Oncol. 2014 Feb;132(2):303-6. doi: 10.1016/j.ygyno.2013.12.028. Epub 2013 Dec 27."},{"pmid":"25701703","type":"RESULT","citation":"Tempfer CB, Winnekendonk G, Solass W, Horvat R, Giger-Pabst U, Zieren J, Rezniczek GA, Reymond MA. Pressurized intraperitoneal aerosol chemotherapy in women with recurrent ovarian cancer: A phase 2 study. Gynecol Oncol. 2015 May;137(2):223-8. doi: 10.1016/j.ygyno.2015.02.009. Epub 2015 Feb 18."},{"pmid":"24849521","type":"RESULT","citation":"Vizzielli G, Costantini B, Tortorella L, Petrillo M, Fanfani F, Chiantera V, Ercoli A, Iodice R, Scambia G, Fagotti A. Influence of intraperitoneal dissemination assessed by laparoscopy on prognosis of advanced ovarian cancer: an exploratory analysis of a single-institution experience. Ann Surg Oncol. 2014 Nov;21(12):3970-7. doi: 10.1245/s10434-014-3783-6. Epub 2014 May 22."}]},"ipdSharingStatementModule":{"ipdSharing":"NO"}},"annotationSection":{"annotationModule":{"unpostedAnnotation":{"unpostedResponsibleParty":"Prof. Giovanni Scambia, Professor, Catholic University of the Sacred Heart","unpostedEvents":[{"type":"RELEASE","date":"2024-03-22"},{"type":"RESET","date":"2024-08-21"}]}}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-10-01","submissionTracking":{"estimatedResultsFirstSubmitDate":"2024-03-22","submissionInfos":[{"releaseDate":"202