{"protocolSection":{"identificationModule":{"nctId":"NCT05383092","orgStudyIdInfo":{"id":"RC31/22/0061"},"organization":{"fullName":"University Hospital, Toulouse","class":"OTHER"},"briefTitle":"Adapted Physical Activity for Children Treated With Cancer and Insulin Sensitivity","officialTitle":"Adapted Physical Activity for Children Treated With Cancer and Insulin Sensitivity","acronym":"APACIS"},"statusModule":{"statusVerifiedDate":"2023-09","overallStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2022-07-11","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2026-12-31","type":"ESTIMATED"},"completionDateStruct":{"date":"2026-12-31","type":"ESTIMATED"},"studyFirstSubmitDate":"2022-05-16","studyFirstSubmitQcDate":"2022-05-16","studyFirstPostDateStruct":{"date":"2022-05-19","type":"ACTUAL"},"lastUpdateSubmitDate":"2023-09-20","lastUpdatePostDateStruct":{"date":"2023-09-21","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"University Hospital, Toulouse","class":"OTHER"}},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"The main objective of this study is to evaluate the evolution of the sensitivity to insulin, a hormone that acts on sugar in the body, as well as other metabolic, motor and nutritional elements of children with cancer, according to the practice of intense physical activities or stretching. In view of the scientific work on this subject, it is expect to observe that the practice of intense physical activities will improve the results of the children in the metabolic, motor and nutritional evaluations, compared to the stretching program.","detailedDescription":"The protocol consists of 6 months of intense physical activity and stretching programs for children with solid cancer or haematological disease, starting at diagnosis. Evaluations will be performed at the first, third and sixth month of the programs and then six and eighteen months after they are stopped. The physical activity sessions will take place in the hospital during hospitalizations or by videoconference when the children are at home. The sessions are adapted to the needs, desires and abilities of the children and will take place two to three times a week. They will be mediated by various activities such as soccer, rugby, darts, muscle strengthening. Inclusion lasts two years."},"conditionsModule":{"conditions":["Pediatric Cancer"],"keywords":["pediatric cancers","exercise","insulin sensibility","metabolic syndrome"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","interventionModelDescription":"Prospective randomized pilot study studying the parameters of two groups receiving physical activity management over a period of 6 months","primaryPurpose":"SUPPORTIVE_CARE","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":60,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Adapted physical activity Strong","type":"EXPERIMENTAL","interventionNames":["Other: Adapted Physical Activity Strong"]},{"label":"Adapted physical activity Soft","type":"ACTIVE_COMPARATOR","interventionNames":["Other: Adapted Physical Activity Strong"]}],"interventions":[{"type":"OTHER","name":"Adapted Physical Activity Strong","description":"Children will practice physical activities combining aerobics and muscle strengthening. They will follow a 30-minute (for prepubescent children) or 60-minute (for pubescent children) Strong adapted physical activity session 2 to 3 times a week during hospitalization periods or by videoconference at home when they are not hospitalized.","armGroupLabels":["Adapted physical activity Soft","Adapted physical activity Strong"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Insulin Sensitivity","description":"Homeostasis Model Assessment of Insulin Resistance","timeFrame":"6 months"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

